/// A wall-clock budget measured on the injected SDK [`Clock`], the only time
/// source the code gate admits in application code.
///
/// The SDK clock reads epoch milliseconds, so in production it can step. The
/// budget therefore accumulates only the forward distance between successive
/// readings: a backwards step counts as zero elapsed time and moves the
/// baseline to the new reading, so it never extends the budget by the size of
/// the step. A forward step is charged in full and can only end a run early.
/// Under a manual (harness) clock the budget advances exactly when the test
/// advances the clock, so a frozen clock leaves only the fuel bound in force.
pub struct WallBudget {
    clock: Clock,
    last_ms: u64,
    spent_ms: u64,
    limit_ms: u64,
}

impl WallBudget {
    /// Start a budget of `limit` on `clock`, from the clock's current reading.
    pub fn start(clock: &Clock, limit: Duration) -> Self {
        Self {
            clock: clock.clone(),
            last_ms: clock.now_ms(),
            spent_ms: 0,
            limit_ms: u64::try_from(limit.as_millis()).unwrap_or(u64::MAX),
        }
    }

    /// Milliseconds charged so far. Never decreases.
    pub fn spent_ms(&mut self) -> u64 {
        let now = self.clock.now_ms();
        self.spent_ms = self
            .spent_ms
            .saturating_add(now.saturating_sub(self.last_ms));
        self.last_ms = now;
        self.spent_ms
    }

    /// Whether the whole budget has been charged.
    pub fn exhausted(&mut self) -> bool {
        self.spent_ms() >= self.limit_ms
    }
}
