    // Instantiate WITHOUT running the start section: the quickjs module's start
    // function is `_start`, which runs the entire guest program. If we let
    // `instantiate` run it, the whole snippet executes UNBOUNDED during
    // instantiation (a `while(true)` loop wedges the worker forever, bypassing
    // the fuel budget entirely). Instead we instantiate no-start and drive
    // `_start` ourselves through the fuel-limited resumable path below, so pure
    // computation is bounded to `fuel` wasm instructions and a runaway loop is
    // aborted deterministically. Terminating traps (`proc_exit`, the
    // `TOOL_PENDING` pending-call trap) surface from the resume as an error and
    // are classified by the formatted error rather than a single variant. Host
    // calls (tool loopback, egress fetch) run BLOCKING inside a resume — they
    // are not fuel-bounded here (egress has its own timeout).
    let outcome = match ModuleInstance::instantiate_no_start(&mut store, module, Some(imports)) {
        Ok(instance) => match instance.func::<(), ()>(&store, "_start") {
            Ok(start) => match start.call_resumable(&mut store, ()) {
                Ok(mut exec) => {
                    // Resume in fixed chunks, accumulating consumed fuel, so the
                    // budget can exceed the interpreter's per-call u32 limit and
                    // a runaway loop is bounded deterministically.
                    const CHUNK: u32 = 4096;
                    let mut consumed: u64 = 0;
                    loop {
                        if budget.exhausted() {
                            break RunOutcome::Fault(
                                "execution exceeded the wall-clock budget".into(),
                            );
                        }
                        let remaining = fuel.saturating_sub(consumed);
                        if remaining == 0 {
                            break RunOutcome::Fault(format!(
                                "execution exceeded the fuel budget (~{fuel} instructions) — the snippet ran too long"
                            ));
                        }
                        let step = remaining.min(CHUNK as u64) as u32;
                        // Charge a whole chunk even when it traps early: conservative,
                        // bounded accounting across host-call replay rounds.
                        charged_fuel = charged_fuel.saturating_add(step as u64);
                        match exec.resume_with_fuel(step) {
                            Ok(crate::wasm::rt::ExecProgress::Completed(())) => {
                                break RunOutcome::Complete { exit: 0 };
                            }
                            Ok(crate::wasm::rt::ExecProgress::Suspended) => {
                                consumed = consumed.saturating_add(step as u64);
                            }
                            Err(e) => break classify_err(&e, &shim),
                        }
                    }
                }
                Err(e) => classify_err(&e, &shim),
            },
            Err(e) => RunOutcome::Fault(format!("no _start export: {e:?}")),
        },
        Err(e) => classify_err(&e, &shim),
    };

