/// Split a stdout buffer into (host requests, final output frame, plain stdout).
fn parse_stdout(raw: &[u8]) -> (Vec<Request>, Option<Value>, String) {
    let s = String::from_utf8_lossy(raw);
    let mut requests = Vec::new();
    let mut output = None;
    let mut user = String::new();
    let mut rest = s.as_ref();
    while let Some(i) = rest.find(FRAME) {
        user.push_str(&rest[..i]);
        let after = &rest[i + FRAME.len()..];
        let end = match after.find('\n') {
            Some(e) => e,
            None => break,
        };
        let line = &after[..end];
        if let Ok(v) = serde_json::from_str::<Value>(line) {
            if v.get("op").is_some() {
                requests.push(Request {
                    index: v.get("i").and_then(|x| x.as_u64()).unwrap_or(0),
                    op: v
                        .get("op")
                        .and_then(|x| x.as_str())
                        .unwrap_or("")
                        .to_string(),
                    args: v.get("args").cloned().unwrap_or(Value::Null),
                });
            } else if v.get("output").is_some() {
                output = Some(v);
            }
        }
        rest = &after[end + 1..];
    }
    user.push_str(rest);
    (requests, output, user)
}

