/// Run a consumer-owned workload with an explicit finite wall budget.
/// Fuel and memory accounting are identical to `execute_with`; only the
/// injected-clock budget differs. Host-call time consumes the same budget.
#[expect(
    clippy::too_many_arguments,
    reason = "caller-owned execution bounds remain explicit"
)]
pub async fn execute_with_wall_limit<F, Fut>(
    program: &Program,
    prelude_extra: &str,
    code: &str,
    input_json: &str,
    is_ts: bool,
    clock_ns: u64,
    max_tool_calls: u32,
    fuel: u64,
    max_output_bytes: usize,
    budget_clock: &Clock,
    wall_limit: Duration,
    mut dispatch: F,
) -> ExecResult
where
    F: FnMut(Request) -> Fut,
    Fut: core::future::Future<Output = Response>,
{
    let program_src = build_program_with(prelude_extra, code, input_json, is_ts);
    let mut responses: Vec<String> = Vec::new();
    let mut rounds = 0u32;
    // One budget spans every replay round and every host call in between.
    let mut budget = WallBudget::start(budget_clock, wall_limit);
    let mut remaining_fuel = fuel;
    loop {
        rounds += 1;
        if rounds > max_tool_calls.saturating_add(2) {
            return ExecResult {
                exit_code: 108,
                output: Value::Null,
                logs: Vec::new(),
                stdout: String::new(),
                stderr: format!("exceeded max tool calls ({max_tool_calls})"),
                tool_calls: responses.len() as u32,
                rounds,
            };
        }
        let run = run_once(
            &program.module,
            &program_src,
            clock_ns,
            &responses,
            remaining_fuel,
            max_output_bytes,
            &mut budget,
        );
        remaining_fuel = remaining_fuel.saturating_sub(run.charged_fuel);
        let (requests, output_frame, user_stdout) = parse_stdout(&run.stdout);

        match run.outcome {
            RunOutcome::Complete { exit } => {
                let (output, logs) = match output_frame {
                    Some(v) => (
                        v.get("output").cloned().unwrap_or(Value::Null),
                        v.get("logs")
                            .and_then(|l| l.as_array())
                            .map(|a| {
                                a.iter()
                                    .filter_map(|x| x.as_str().map(|s| s.to_string()))
                                    .collect()
                            })
                            .unwrap_or_default(),
                    ),
                    None => (Value::Null, Vec::new()),
                };
                let truncated_note = if run.output_truncated {
                    "\n[output truncated at max_output_bytes]"
                } else {
                    ""
                };
                return ExecResult {
                    exit_code: run.exit_code.unwrap_or(exit),
                    output,
                    logs,
                    stdout: user_stdout,
                    stderr: format!("{}{}", String::from_utf8_lossy(&run.stderr), truncated_note),
                    tool_calls: responses.len() as u32,
                    rounds,
                };
            }
            RunOutcome::ToolPending => {
                // Service the next unanswered request.
                let next = match requests.get(responses.len()) {
                    Some(r) => r.clone(),
                    None => {
                        return ExecResult {
                            exit_code: 109,
                            output: Value::Null,
                            logs: Vec::new(),
                            stdout: user_stdout,
                            stderr: "tool pending but no request frame found".to_string(),
                            tool_calls: responses.len() as u32,
                            rounds,
                        };
                    }
                };
                let resp = dispatch(next).await;
                responses.push(resp.encode());
            }
            RunOutcome::Fault(msg) => {
                return ExecResult {
                    exit_code: 110,
                    output: Value::Null,
                    logs: Vec::new(),
                    stdout: user_stdout,
                    stderr: format!(
                        "worker fault: {msg}\n{}",
                        String::from_utf8_lossy(&run.stderr)
                    ),
                    tool_calls: responses.len() as u32,
                    rounds,
                };
            }
        }
    }
}
